          "status": 503,
          "protocol": "HTTP/1.1",
          "json": {
            "backend_id": "fixture-a",
            "status": 503
          }
        }
      },
      {
        "name": "fixture-controlled-delay",
        "feature": "controlled-delay",
        "polarity": "observation",
        "request": {
          "path": "/delay",
          "headers": {
            "X-Fixture-Delay-Ms": "20"
          }
